challenge.solution:
#include <iostream>
using namespace std;

int main() {
    long long a, b;
    char op;
    cin >> a >> op >> b;
    switch (op) {
        case '+': cout << a + b << "\n"; break;
        case '-': cout << a - b << "\n"; break;
        case '*': cout << a * b << "\n"; break;
        case '/':
            if (b == 0) cout << "error\n";
            else cout << a / b << "\n";
            break;
        case '%':
            if (b == 0) cout << "error\n";
            else cout << a % b << "\n";
            break;
    }
    return 0;
}

