#include <iostream>
#include <vector>
using namespace std;

// v is read-only and not copied; lo and hi are written for the caller
void minMax(const vector<int>& v, int& lo, int& hi) {
    lo = hi = v[0];
    for (int x : v) {
        if (x < lo) lo = x;
        if (x > hi) hi = x;
    }
}

int main() {
    vector<int> v = {4, -2, 9, 7};
    int lo, hi;
    minMax(v, lo, hi);
    cout << lo << " " << hi << "\n";
    return 0;
}

