challenge.solution:
#include <iostream>
#include <utility>
using namespace std;

void sortThree(int& a, int& b, int& c) {
    if (a > b) swap(a, b);
    if (b > c) swap(b, c);
    if (a > b) swap(a, b);
}

int main() {
    int a, b, c;
    cin >> a >> b >> c;
    sortThree(a, b, c);
    cout << a << " " << b << " " << c << "\n";
    return 0;
}

