         << binary_search(v.begin(), v.end(), 4) << "\n";            // 1 0
    cout << lower_bound(v.begin(), v.end(), 3) - v.begin() << "\n";  // 1
    cout << upper_bound(v.begin(), v.end(), 3) - v.begin() << "\n";  // 4
