         << upper_bound(v.begin(), v.end(), 3) - lower_bound(v.begin(), v.end(), 3) << "\n";
    auto it = lower_bound(v.begin(), v.end(), 100);
    if (it == v.end()) cout << "nothing >= 100\n";
