#include <iostream>
#include <string>
using namespace std;

class Account {
public:
    void deposit(long long x) { balance_ += x; }
    bool withdraw(long long x) {
        if (x > balance_) return false;
        balance_ -= x;
        return true;
    }
    long long balance() const { return balance_; }
private:
    long long balance_ = 0;
};

int main() {
    int q;
    cin >> q;
    Account acc;
    while (q--) {
        string cmd;
        cin >> cmd;
        if (cmd == "deposit") {
            long long x;
            cin >> x;
            acc.deposit(x);
        } else if (cmd == "withdraw") {
            long long x;
            cin >> x;
            if (!acc.withdraw(x)) cout << "denied\n";
        } else {
            cout << acc.balance() << "\n";
        }
    }
    return 0;
}

