template <typename T>
T biggest(const vector<T>& v) {
    T best = v[0];
    for (const T& x : v)
        if (x > best) best = x;
    return best;
}

int main() {
    vector<int> a = {3, 9, 2};
    vector<double> b = {1.5, -2.25, 0.75};
    vector<string> c = {"pear", "apple", "zucchini", "fig"};
    cout << biggest(a) << " " << biggest(b) << " " << biggest(c) << "\n";
