challenge.solution:
import sys

class Account:
    def __init__(self):
        self.balance = 0

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            return False
        self.balance -= amount
        return True

acc = Account()
for line in sys.stdin:
    parts = line.split()
    if not parts:
        continue
    if parts[0] == 'deposit':
        acc.deposit(int(parts[1]))
    elif parts[0] == 'withdraw':
        if not acc.withdraw(int(parts[1])):
            print('insufficient')
    else:
        print(acc.balance)
